##~~Join the bedrock TM1 community on GitHub https://github.com/cubewise-code/bedrock Ver 5.0.0~~##
#################################################################################################

#Region @DOC
#### Description:
#Authenticates to a local or remote TM1/Planning Analytics instance and returns the connection details as a JSON string in `sBedrockReturnValue`, for use by subsequent bedrock HTTP processes.
#
#### How to Use:
#
#Connections are defined in regions further down this Prolog, in the same way a TM1py `config.ini` has one `[section]` per connection.
#
#To add a connection:
#1. Copy the whole `"<database_name>" Database Connection Details` region, from its `#Region` line to its `#EndRegion` line.
#2. Paste it below the last connection region, above the `Extract Database Connection Parameters` region.
#3. Rename the region title and set `sConnectionName`. This is the name callers pass in `pConnectionName` (like the `[section]` name in a `config.ini`), and it must be unique.
#4. Fill in only the fields your authentication mode needs (see **Authentication Modes** below) and leave the rest as `''`.
#5. Optionally set `sThisDatabaseName` to the connection used when `pConnectionName` is blank.
#
#Leave the template region in place so it can be copied again.
#
#Here is an example of the filled-in fields for IBM Cloud (Planning Analytics SaaS), with all other fields left as `''`:
#```
#sConnectionName = 'Production';
#
#pAddress  = 'us-east-1.planninganalytics.saas.ibm.com';
#pAPIKey   = CellGetS( 'Global_Assumptions', 'TM1 Connection API Key', 'String Value' );
#pTenant   = '<tenant_id>';
#pDatabase = '<database_name>';
#```
#
#> [!TIP]
#> Use a lookup for secrets (as with `pAPIKey` above) so they are not stored in plain text in this process.
#
#### Authentication Modes:
#
#| `pAuthMode` | Required fields | Notes |
#|---|---|---|
#| `BASIC` | `pUser`, `pPassword`, and `pAddress` or `pBaseURL` | Native TM1 user/password. Used when no other mode is detected. |
#| `CAM` | `pUser`, `pPassword`, `pNamespace`, and `pAddress` or `pBaseURL` | CAM namespace authentication. |
#| `IBM_CLOUD_API_KEY` | `pAPIKey`, `pAddress`, `pTenant`, `pDatabase` | `pIAMURL` can stay `''` to use the default IBM Cloud IAM URL. |
#| `ACCESS_TOKEN` | `pAccessToken`, and `pAddress` or `pBaseURL` | Pre-issued bearer token. |
#| `SERVICE_TO_SERVICE` | `pApplicationClientId`, `pApplicationClientSecret`, `pUser`, `pInstance`, `pDatabase`, `pAddress` | PA Engine client credentials. |
#
#- `pPort` and `pSSL` (1 = https, 0 = http) are optional for all modes except `IBM_CLOUD_API_KEY`, which always uses https.
#- If `pAuthMode` is left as `''`, it is auto-detected in this order: `pAPIKey` set → `IBM_CLOUD_API_KEY`, client id and secret set → `SERVICE_TO_SERVICE`, `pAccessToken` set → `ACCESS_TOKEN`, `pNamespace` set → `CAM`, otherwise `BASIC`.
#- `pBaseURL` overrides the URL built from `pAddress`/`pPort`/`pSSL` for all modes except `IBM_CLOUD_API_KEY` and `SERVICE_TO_SERVICE`, which have fixed URL formats.
#
#### Parameters:
#
#- `pConnectionName`: the `sConnectionName` of the connection region to use. If blank, `sThisDatabaseName` is used.
#- `pSessionContext`: sent as the `TM1-SessionContext` header (default = `Bedrock`).
#- `pLogOutput`: 1 = write info to the TM1 server log. Passwords, secrets and tokens are never logged.
#- `pStrictErrorHandling`: 1 = `ProcessQuit` on error, 0 = `ProcessBreak`.
#- `pRunProcessMode`: 1 = also write `sBedrockReturnValue` to `<pConnectionName>.json`, 0 = only return it (default = 0). Used by callers that start this process with `RunProcess`, e.g. when connection values are read from a cube, and then read the file back.
#- `pJson`: OPTIONAL: a JSON Object of parameter values that override the passed parameters, e.g. `{"pRunProcessMode": 1}`.
#
#> [!IMPORTANT]
#> The values in the connection region replace any connection parameters passed to this process (`pAddress`, `pUser`, `pAPIKey`, etc.). Only `pConnectionName`, `pSessionContext`, `pLogOutput`, `pStrictErrorHandling` and `pRunProcessMode` are taken from the caller.
#
#### Return Value:
#
#`sBedrockReturnValue` is set to:
#```json
#{
#  "sURL": <string, the base API URL for all subsequent requests>,
#  "sAuthMode": <string, the resolved authentication mode>,
#  "sAuthHeader": <string, the Authorization header value for bearer-token modes, or "">,
#  "sSID": <string, the session cookie as name=value, e.g. "paSession=...", or "">,
#  "sVer": <string, the TM1 product version, e.g. "12.4.0">,
#  "sDBN": <string, the database name>
#}
#```
#Calling processes must authenticate every subsequent HTTP request:
#- If `sAuthHeader` is set (`IBM_CLOUD_API_KEY`, `ACCESS_TOKEN`), send `Authorization: <sAuthHeader>`.
#- Otherwise, if `sSID` is set (`BASIC`, `CAM`, `SERVICE_TO_SERVICE`), send `Cookie: <sSID>`.
#
#Here is an example of calling this process from another process:
#```
#ExecuteProcess( '}bedrock.session.start', 'pConnectionName', 'Production' );
#sConnectionDetails = sBedrockReturnValue;
#sURL        = JsonToString( sConnectionDetails, '/sURL' );
#sAuthHeader = JsonToString( sConnectionDetails, '/sAuthHeader' );
#sSID        = JsonToString( sConnectionDetails, '/sSID' );
#```
#
#> [!WARNING]
#> With `pRunProcessMode = 1`, the output file contains a live token (`sAuthHeader`) or session cookie (`sSID`).
#
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants
cThisProcName = GetProcessName();
cUserName     = TM1User();
cTimeStamp    = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt    = NumberToString( INT( RAND( ) * 1000000000 ) );
cTemp         = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sMessages     = '{"Process": "'|cThisProcName|'", "User": "'|cUserName|'", "Info": ["Process: '''|cThisProcName|''' run by User: '''|cUserName|'''."], "Error": []}';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );

pDefaultParameters = '{
  "pConnectionName":          "",
  "pAddress":                 "",
  "pPort":                    "",
  "pSSL":                     1,
  "pBaseURL":                 "",
  "pUser":                    "",
  "pPassword":                "",
  "pNamespace":               "",
  "pAuthMode":                "",
  "pAPIKey":                  "",
  "pIAMURL":                  "https://iam.cloud.ibm.com/identity/token",
  "pTenant":                  "",
  "pDatabase":                "",
  "pInstance":                "",
  "pAccessToken":             "",
  "pApplicationClientId":     "",
  "pApplicationClientSecret": "",
  "pSessionContext":          "Bedrock",
  "pLogOutput":               0,
  "pStrictErrorHandling":     0,
  "pRunProcessMode":          0
}';

pPassedParameters = '{
  "pConnectionName":          '|StringToJson( pConnectionName          )|',
  "pAddress":                 '|StringToJson( pAddress                 )|',
  "pPort":                    '|StringToJson( pPort                    )|',
  "pSSL":                     '|NumberToString( pSSL                   )|',
  "pBaseURL":                 '|StringToJson( pBaseURL                 )|',
  "pUser":                    '|StringToJson( pUser                    )|',
  "pPassword":                '|StringToJson( pPassword                )|',
  "pNamespace":               '|StringToJson( pNamespace               )|',
  "pAuthMode":                '|StringToJson( pAuthMode                )|',
  "pAPIKey":                  '|StringToJson( pAPIKey                  )|',
  "pIAMURL":                  '|StringToJson( pIAMURL                  )|',
  "pTenant":                  '|StringToJson( pTenant                  )|',
  "pDatabase":                '|StringToJson( pDatabase                )|',
  "pInstance":                '|StringToJson( pInstance                )|',
  "pAccessToken":             '|StringToJson( pAccessToken             )|',
  "pApplicationClientId":     '|StringToJson( pApplicationClientId     )|',
  "pApplicationClientSecret": '|StringToJson( pApplicationClientSecret )|',
  "pSessionContext":          '|StringToJson( pSessionContext           )|',
  "pLogOutput":               '|NumberToString( pLogOutput             )|',
  "pStrictErrorHandling":     '|NumberToString( pStrictErrorHandling   )|',
  "pRunProcessMode":          '|NumberToString( pRunProcessMode        )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );

### Read final resolved values back from merged JSON
pConnectionName          =                 JsonToString( pJson, '/pConnectionName'          );
pAddress                 =                 JsonToString( pJson, '/pAddress'                 );
pPort                    =                 JsonToString( pJson, '/pPort'                    );
pSSL                     = StringToNumber( JsonToString( pJson, '/pSSL'                     ) );
pBaseURL                 =                 JsonToString( pJson, '/pBaseURL'                 );
pUser                    =                 JsonToString( pJson, '/pUser'                    );
pPassword                =                 JsonToString( pJson, '/pPassword'                );
pNamespace               =                 JsonToString( pJson, '/pNamespace'               );
pAuthMode                =                 JsonToString( pJson, '/pAuthMode'                );
pAPIKey                  =                 JsonToString( pJson, '/pAPIKey'                  );
pIAMURL                  =                 JsonToString( pJson, '/pIAMURL'                  );
pTenant                  =                 JsonToString( pJson, '/pTenant'                  );
pDatabase                =                 JsonToString( pJson, '/pDatabase'                );
pInstance                =                 JsonToString( pJson, '/pInstance'                );
pAccessToken             =                 JsonToString( pJson, '/pAccessToken'             );
pApplicationClientId     =                 JsonToString( pJson, '/pApplicationClientId'     );
pApplicationClientSecret =                 JsonToString( pJson, '/pApplicationClientSecret' );
pSessionContext          =                 JsonToString( pJson, '/pSessionContext'           );
pLogOutput               = StringToNumber( JsonToString( pJson, '/pLogOutput'               ) );
pStrictErrorHandling     = StringToNumber( JsonToString( pJson, '/pStrictErrorHandling'     ) );
pRunProcessMode          = StringToNumber( JsonToString( pJson, '/pRunProcessMode'          ) );

### Strip only the non-sensitive parameters for logging (never log password / secret / token)
pLoggableParameters = '{
  "pConnectionName":      '|StringToJson( pConnectionName  )|',
  "pAddress":             '|StringToJson( pAddress         )|',
  "pPort":                '|StringToJson( pPort            )|',
  "pSSL":                 '|NumberToString( pSSL           )|',
  "pBaseURL":             '|StringToJson( pBaseURL         )|',
  "pUser":                '|StringToJson( pUser            )|',
  "pNamespace":           '|StringToJson( pNamespace       )|',
  "pAuthMode":            '|StringToJson( pAuthMode        )|',
  "pTenant":              '|StringToJson( pTenant          )|',
  "pDatabase":            '|StringToJson( pDatabase        )|',
  "pInstance":            '|StringToJson( pInstance        )|',
  "pApplicationClientId": '|StringToJson( pApplicationClientId )|',
  "pSessionContext":      '|StringToJson( pSessionContext  )|',
  "pRunProcessMode":      '|NumberToString( pRunProcessMode )|'
}';
sMessages = JsonAdd( sMessages, '/Info/0', pLoggableParameters );

IF( pLogOutput = 1 );
  LogOutput( 'INFO', JsonToString( sMessages, '/Info/0' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

sTotalConnectionsJson = '{}';
sThisDatabaseName = 'bedrock-5-dev';

IF( pConnectionName @= '' );
  pConnectionName = sThisDatabaseName;
ENDIF;

#################################################################################################
#Region - "<database_name>" Database Connection Details

sConnectionName = '<database_name>';

# CONNECTION PARAMETERS (fill in only what your auth mode needs, leave the rest as '')
pAddress                 = '';
pPort                    = '';
pSSL                     = 1 ;
pBaseURL                 = '';
pUser                    = '';
pPassword                = '';
pNamespace               = '';
pAuthMode                = '';
pAPIKey                  = '';
pIAMURL                  = '';
pTenant                  = '';
pDatabase                = '';
pInstance                = '';
pAccessToken             = '';
pApplicationClientId     = '';
pApplicationClientSecret = '';

# Add Connection Details to a JSON Object
sConnectionJson = '{
  "pAddress":                 '|StringToJson( pAddress                 )|',
  "pPort":                    '|StringToJson( pPort                    )|',
  "pSSL":                     '|NumberToString( pSSL                   )|',
  "pBaseURL":                 '|StringToJson( pBaseURL                 )|',
  "pUser":                    '|StringToJson( pUser                    )|',
  "pPassword":                '|StringToJson( pPassword                )|',
  "pNamespace":               '|StringToJson( pNamespace               )|',
  "pAuthMode":                '|StringToJson( pAuthMode                )|',
  "pAPIKey":                  '|StringToJson( pAPIKey                  )|',
  "pIAMURL":                  '|StringToJson( pIAMURL                  )|',
  "pTenant":                  '|StringToJson( pTenant                  )|',
  "pDatabase":                '|StringToJson( pDatabase                )|',
  "pInstance":                '|StringToJson( pInstance                )|',
  "pAccessToken":             '|StringToJson( pAccessToken             )|',
  "pApplicationClientId":     '|StringToJson( pApplicationClientId     )|',
  "pApplicationClientSecret": '|StringToJson( pApplicationClientSecret )|'
}';

sTotalConnectionsJson = JsonAdd( sTotalConnectionsJson, sConnectionName, sConnectionJson );

#EndRegion - "<database_name>" Database Connection Details
#################################################################################################


#Region - Extract Database Connection Parameters
sConnectionDetailsJson = JsonGet( sTotalConnectionsJson, pConnectionName );

pAddress                 =                 JsonToString( sConnectionDetailsJson, '/pAddress'                 );
pPort                    =                 JsonToString( sConnectionDetailsJson, '/pPort'                    );
pSSL                     = StringToNumber( JsonToString( sConnectionDetailsJson, '/pSSL'                     ) );
pBaseURL                 =                 JsonToString( sConnectionDetailsJson, '/pBaseURL'                 );
pUser                    =                 JsonToString( sConnectionDetailsJson, '/pUser'                    );
pPassword                =                 JsonToString( sConnectionDetailsJson, '/pPassword'                );
pNamespace               =                 JsonToString( sConnectionDetailsJson, '/pNamespace'               );
pAuthMode                =                 JsonToString( sConnectionDetailsJson, '/pAuthMode'                );
pAPIKey                  =                 JsonToString( sConnectionDetailsJson, '/pAPIKey'                  );
pIAMURL                  =                 JsonToString( sConnectionDetailsJson, '/pIAMURL'                  );
pTenant                  =                 JsonToString( sConnectionDetailsJson, '/pTenant'                  );
pDatabase                =                 JsonToString( sConnectionDetailsJson, '/pDatabase'                );
pInstance                =                 JsonToString( sConnectionDetailsJson, '/pInstance'                );
pAccessToken             =                 JsonToString( sConnectionDetailsJson, '/pAccessToken'             );
pApplicationClientId     =                 JsonToString( sConnectionDetailsJson, '/pApplicationClientId'     );
pApplicationClientSecret =                 JsonToString( sConnectionDetailsJson, '/pApplicationClientSecret' );
#EndRegion - Extract Database Connection Parameters


#################################################################################################
#Region - Auto-Detect Auth Mode

### Mirror the _determine_auth_mode logic from TM1py RestService
IF( pAuthMode @= '' );

  IF( pAPIKey @<> '' );
    pAuthMode = 'IBM_CLOUD_API_KEY';

  ELSEIF( pApplicationClientId @<> '' & pApplicationClientSecret @<> '' );
    pAuthMode = 'SERVICE_TO_SERVICE';

  ELSEIF( pAccessToken @<> '' );
    pAuthMode = 'ACCESS_TOKEN';

  ELSEIF( pNamespace @<> '' );
    pAuthMode = 'CAM';

  ELSE;
    pAuthMode = 'BASIC';

  ENDIF;

ENDIF;

IF( pLogOutput = 1 );
  LogOutput( 'INFO', 'Auth mode resolved to: ' | pAuthMode );
ENDIF;

#EndRegion - Auto-Detect Auth Mode
#################################################################################################

#################################################################################################
#Region - Validate Parameters

### Shared address/port check for modes that require them
IF( pAuthMode @= 'BASIC' % pAuthMode @= 'CAM' % pAuthMode @= 'SERVICE_TO_SERVICE' );
  IF( pBaseURL @= '' & pAddress @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"pAddress or pBaseURL is required."' );
  ENDIF;
ENDIF;

IF( pAuthMode @= 'BASIC' % pAuthMode @= 'CAM' );
  IF( pUser @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"pUser is required for BASIC and CAM authentication."' );
  ENDIF;
  IF( pPassword @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"pPassword is required for BASIC and CAM authentication."' );
  ENDIF;
ENDIF;

IF( pAuthMode @= 'CAM' );
  IF( pNamespace @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"pNamespace is required for CAM authentication."' );
  ENDIF;
ENDIF;

IF( pAuthMode @= 'IBM_CLOUD_API_KEY' );
  IF( pAPIKey @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"pAPIKey is required for IBM_CLOUD_API_KEY authentication."' );
  ENDIF;
  IF( pAddress @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"pAddress is required for IBM_CLOUD_API_KEY authentication."' );
  ENDIF;
  IF( pTenant @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"pTenant is required for IBM_CLOUD_API_KEY authentication."' );
  ENDIF;
  IF( pDatabase @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"pDatabase is required for IBM_CLOUD_API_KEY authentication."' );
  ENDIF;
ENDIF;

IF( pAuthMode @= 'ACCESS_TOKEN' );
  IF( pAccessToken @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"pAccessToken is required for ACCESS_TOKEN authentication."' );
  ENDIF;
  IF( pBaseURL @= '' & pAddress @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"pAddress or pBaseURL is required for ACCESS_TOKEN authentication."' );
  ENDIF;
ENDIF;

IF( pAuthMode @= 'SERVICE_TO_SERVICE' );
  IF( pApplicationClientId @= '' % pApplicationClientSecret @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"pApplicationClientId and pApplicationClientSecret are required for SERVICE_TO_SERVICE authentication."' );
  ENDIF;
  IF( pInstance @= '' % pDatabase @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"pInstance and pDatabase are required for SERVICE_TO_SERVICE authentication."' );
  ENDIF;
  IF( pUser @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"pUser is required for SERVICE_TO_SERVICE authentication."' );
  ENDIF;
ENDIF;

IF( JsonSize( sMessages, '/Error' ) <> 0 );
  IF( pLogOutput = 1 );
    LogOutput( 'ERROR', 'Validation failed: ' | JsonToString( sMessages, '/Error' ) );
  ENDIF;
  IF( pStrictErrorHandling = 1 );
    ProcessQuit;
  ELSE;
    ProcessBreak;
  ENDIF;
ENDIF;

#EndRegion - Validate Parameters
#################################################################################################

#################################################################################################
#Region - Construct Base URL

### Mirror _construct_service_and_auth_root from TM1py RestService

sScheme   = IF( pSSL = 1, 'https', 'http' );
sPortPart = IF( pPort @= '', '', ':' | pPort );
sAddress  = IF( pAddress @= '', 'localhost', pAddress );

IF( pAuthMode @= 'IBM_CLOUD_API_KEY' );
  ### https://{address}/api/{tenant}/v0/tm1/{database}
  sBaseURL = 'https://' | pAddress | '/api/' | pTenant | '/v0/tm1/' | pDatabase;

ELSEIF( pAuthMode @= 'SERVICE_TO_SERVICE' );
  ### http{s}://{address}:{port}/{instance}/api/v1/Databases('{database}')
  sBaseURL = sScheme | '://' | sAddress | sPortPart | '/' | pInstance | '/api/v1/Databases(''' | pDatabase | ''')';

ELSEIF( pBaseURL @<> '' );
  ### Caller supplied an explicit base URL — normalise it to end with /api/v1
  sBaseURL = pBaseURL;
  IF( SubSt( sBaseURL, Long( sBaseURL ) - 6, 7 ) @<> '/api/v1' );
    IF( SubSt( sBaseURL, Long( sBaseURL ), 1 ) @= '/' );
      sBaseURL = sBaseURL | 'api/v1';
    ELSE;
      sBaseURL = sBaseURL | '/api/v1';
    ENDIF;
  ENDIF;

ELSE;
  ### Standard v11 / v12 PA Proxy: http{s}://{address}:{port}/api/v1
  sBaseURL = sScheme | '://' | sAddress | sPortPart | '/api/v1';

ENDIF;

IF( pLogOutput = 1 );
  LogOutput( 'INFO', 'Base URL: ' | sBaseURL );
ENDIF;

#EndRegion - Construct Base URL
#################################################################################################

#################################################################################################
#Region - Build Authorization Header & Authenticate

### sAuthHeader is kept only for stateless bearer-token modes.
### sSID is the session cookie ("name=value", e.g. paSession=... or TM1SessionId=...) for cookie-based modes.
### Requests here pass pLogOutput rather than pJson, because this process's pJson contains a
### "pUser" key that }bedrock.process.execute_http_request would treat as its own pUser (basic auth).
sAuthHeader  = '';
sLoginHeader = '';
sSID         = '';
sVer         = '';
sDBN         = pDatabase;
sSetCookie   = '';
sVerJson     = '';

### ── BASIC ──────────────────────────────────────────────────────────────────
IF( pAuthMode @= 'BASIC' );
  sLoginHeader = 'Basic ' | Base64Encode( pUser | ':' | pPassword );

### ── CAM ────────────────────────────────────────────────────────────────────
ELSEIF( pAuthMode @= 'CAM' );
  ### CAMNamespace token = Base64( user:password:namespace )
  sLoginHeader = 'CAMNamespace ' | Base64Encode( pUser | ':' | pPassword | ':' | pNamespace );

### ── IBM_CLOUD_API_KEY ───────────────────────────────────────────────────────
ELSEIF( pAuthMode @= 'IBM_CLOUD_API_KEY' );

  ### Exchange the API key for an IAM access token
  sIAMURL  = IF( pIAMURL @= '', 'https://iam.cloud.ibm.com/identity/token', pIAMURL );
  sIAMBody = 'grant_type=urn%3Aibm%3Aparams%3Aoauth%3Agrant-type%3Aapikey&apikey=' | pAPIKey;

  ExecuteProcess( '}bedrock.process.execute_http_request',
    'pMethod',    'POST',
    'pURL',       sIAMURL,
    'pHeaders',   '["Accept: application/json", "Content-Type: application/x-www-form-urlencoded"]',
    'pBody',      sIAMBody,
    'pContext',   '',
    'pLogOutput', pLogOutput
  );
  sAccessToken = JsonToString( sBedrockReturnValue, '/body/access_token' );

  IF( sAccessToken @= '' );
    sMessages = JsonAdd( sMessages, '/Error/0', '"IBM Cloud IAM authentication failed: access_token not found in response."' );
    IF( pLogOutput = 1 );
      LogOutput( 'ERROR', 'IAM response status: ' | JsonToString( sBedrockReturnValue, '/status_code' ) );
    ENDIF;
    IF( pStrictErrorHandling = 1 );
      ProcessQuit;
    ELSE;
      ProcessBreak;
    ENDIF;
  ENDIF;

  ### Bearer token must be forwarded on every subsequent request
  sAuthHeader  = 'Bearer ' | sAccessToken;
  sLoginHeader = sAuthHeader;

### ── ACCESS_TOKEN ────────────────────────────────────────────────────────────
ELSEIF( pAuthMode @= 'ACCESS_TOKEN' );
  sAuthHeader  = 'Bearer ' | pAccessToken;
  sLoginHeader = sAuthHeader;

### ── SERVICE_TO_SERVICE ──────────────────────────────────────────────────────
ELSEIF( pAuthMode @= 'SERVICE_TO_SERVICE' );

  ### Auth endpoint: http{s}://{address}:{port}/{instance}/auth/v1/session
  sAuthURL       = sScheme | '://' | sAddress | sPortPart | '/' | pInstance | '/auth/v1/session';
  sS2SAuthHeader = 'Basic ' | Base64Encode( pApplicationClientId | ':' | pApplicationClientSecret );
  sS2SBody       = '{"User": ' | StringToJson( pUser ) | '}';

  ExecuteProcess( '}bedrock.process.execute_http_request',
    'pMethod',          'POST',
    'pURL',             sAuthURL,
    'pHeaders',         '['|StringToJson( 'Authorization: ' | sS2SAuthHeader )|', "Content-Type: application/json"]',
    'pBody',            sS2SBody,
    'pResponseHeaders', '["Set-Cookie"]',
    'pContext',         pSessionContext,
    'pLogOutput',       pLogOutput
  );
  sSetCookie = JsonToString( sBedrockReturnValue, '/headers/Set-Cookie' );

ENDIF;

### ── Login request (all modes except SERVICE_TO_SERVICE) ─────────────────────
### Also reads the product version and captures the session cookie.
IF( pAuthMode @<> 'SERVICE_TO_SERVICE' );
  ExecuteProcess( '}bedrock.process.execute_http_request',
    'pMethod',          'GET',
    'pURL',             sBaseURL | '/Configuration/ProductVersion/$value',
    'pHeaders',         '['|StringToJson( 'Authorization: ' | sLoginHeader )|']',
    'pResponseHeaders', '["Set-Cookie"]',
    'pContext',         pSessionContext,
    'pLogOutput',       pLogOutput
  );
  nStatusCode = StringToNumber( JsonToString( sBedrockReturnValue, '/status_code' ) );
  IF( nStatusCode >= 400 );
    sMessages = JsonAdd( sMessages, '/Error/0', StringToJson( 'Authentication failed for connection ''' | pConnectionName | ''' with status code ' | NumberToString( nStatusCode ) | '.' ) );
    IF( pLogOutput = 1 );
      LogOutput( 'ERROR', JsonToString( sMessages, '/Error/0' ) );
    ENDIF;
    IF( pStrictErrorHandling = 1 );
      ProcessQuit;
    ELSE;
      ProcessBreak;
    ENDIF;
  ENDIF;
  sSetCookie = JsonToString( sBedrockReturnValue, '/headers/Set-Cookie' );
  sVerJson   = JsonGet( sBedrockReturnValue, '/body' );
ENDIF;

### ── Session cookie: keep the "name=value" pair of the TM1 session cookie ────
nStart = SCAN( 'paSession=', sSetCookie );
IF( nStart = 0 );
  nStart = SCAN( 'TM1SessionId=', sSetCookie );
ENDIF;
IF( nStart = 0 );
  nStart = 1;
ENDIF;
sSID = DELET( sSetCookie, 1, nStart - 1 );
nEnd = SCAN( ';', sSID );
IF( nEnd > 0 );
  sSID = SUBST( sSID, 1, nEnd - 1 );
ENDIF;
sSID = TRIM( sSID );

### Headers for the remaining requests in this process
sRequestHeaders = '[]';
IF( sAuthHeader @<> '' );
  sRequestHeaders = JsonAdd( sRequestHeaders, '', StringToJson( 'Authorization: ' | sAuthHeader ) );
ELSEIF( sSID @<> '' );
  sRequestHeaders = JsonAdd( sRequestHeaders, '', StringToJson( 'Cookie: ' | sSID ) );
ENDIF;

### ── Product version (SERVICE_TO_SERVICE has not read it yet) ────────────────
IF( pAuthMode @= 'SERVICE_TO_SERVICE' );
  ExecuteProcess( '}bedrock.process.execute_http_request',
    'pMethod',    'GET',
    'pURL',       sBaseURL | '/Configuration/ProductVersion/$value',
    'pHeaders',   sRequestHeaders,
    'pContext',   pSessionContext,
    'pLogOutput', pLogOutput
  );
  sVerJson = JsonGet( sBedrockReturnValue, '/body' );
ENDIF;
IF( JsonType( sVerJson ) @= 'string' );
  sVer = JsonToString( sVerJson );
ELSE;
  sVer = sVerJson;
ENDIF;

### ── Database name, when it is not already known from pDatabase ─────────────
IF( sDBN @= '' );
  ExecuteProcess( '}bedrock.process.execute_http_request',
    'pMethod',    'GET',
    'pURL',       sBaseURL | '/Configuration/ServerName/$value',
    'pHeaders',   sRequestHeaders,
    'pContext',   pSessionContext,
    'pLogOutput', pLogOutput
  );
  sDBNJson = JsonGet( sBedrockReturnValue, '/body' );
  IF( JsonType( sDBNJson ) @= 'string' );
    sDBN = JsonToString( sDBNJson );
  ELSE;
    sDBN = sDBNJson;
  ENDIF;
ENDIF;

IF( pLogOutput = 1 );
  LogOutput( 'INFO', 'Authentication complete for mode: ' | pAuthMode | ' | Version: ' | sVer | ' | Database: ' | sDBN );
ENDIF;

#EndRegion - Build Authorization Header & Authenticate
#################################################################################################

#################################################################################################
#Region - Build Return Value

### sBedrockReturnValue is consumed by calling processes as their connection context.
###
### sURL        – The base API URL for all subsequent requests.
### sAuthMode   – The resolved authentication mode (informational).
### sAuthHeader – Bearer token header value for IBM_CLOUD_API_KEY and ACCESS_TOKEN. Empty otherwise.
### sSID        – Session cookie as "name=value" for cookie-based modes. May also be set for bearer modes.
### sVer        – TM1 product version, e.g. 12.4.0.
### sDBN        – Database name.
###
### Calling processes send "Authorization: <sAuthHeader>" when it is set, otherwise "Cookie: <sSID>".

sBedrockReturnValue = '{' |
  '"sURL":        ' | StringToJson( sBaseURL    ) | ',' |
  '"sAuthMode":   ' | StringToJson( pAuthMode   ) | ',' |
  '"sAuthHeader": ' | StringToJson( sAuthHeader ) | ',' |
  '"sSID":        ' | StringToJson( sSID        ) | ',' |
  '"sVer":        ' | StringToJson( sVer        ) | ',' |
  '"sDBN":        ' | StringToJson( sDBN        ) |
'}';

IF( pLogOutput = 1 );
  ### Log without the auth header or cookie to avoid leaking secrets to the message log
  LogOutput( 'INFO', 'Session started. sURL=' | sBaseURL | ' sAuthMode=' | pAuthMode );
ENDIF;

#EndRegion - Build Return Value
#################################################################################################

#################################################################################################
#Region - Cleanup

IF( pRunProcessMode = 1 );
  DatasourceASCIIQuoteCharacter='';
  TextOutput( '^'|pConnectionName|'.json', sBedrockReturnValue );
ENDIF;

#EndRegion - Cleanup
#################################################################################################
